        initiate("alice", ev, "bob");
        fixClock(BASE.plusSeconds(14400));
        accept("bob", ev);

        // 包内容逐字节不变
        assertThat(getPackage(packageKey).getResponse().getContentAsString())
                .isEqualTo(frozenBody);
