        assertThat(pkg.get("deliveredBy").asText()).isEqualTo("dave");
        assertThat(pkg.get("deliveredAt").isNull()).isFalse();

        // 已交付：不可撤销、不可增删、不可重复交付
        MvcResult revokeDelivered = revoke("carol", packageKey, uniqueKey("CMD"), "发现问题");
